| M   | -- *saleNum*      | int  | 剩余售卖数量                  |
| M   | -- *remainTime*   | int  | 剩余售卖时间                  |
| M   | -- *packages*     | map  | 今日套餐信息，key=位置id         |
| M   | \\-- *recipeType* | int  | 大类id(强制要求)              |
| M   | \\-- *recipeId*   | int  | 菜谱id]]
function OverseaManageMenuSettingPutNode:RefreshShowInfo(menuData,index,aniName)
    self.index = index
    self.menuData = menuData
    local isMeet = self:IsMeetRecipes(menuData)
    local desc = MaidCoffeeMgr:GetCurMenuDes(index,isMeet)
    if desc ~= "" then
        CfUtils.FillText(self.TextDesc1.gameObject,desc)
        CfUtils.FillText(self.TextDesc2.gameObject,desc)
    end
    self:SetFoodTypeInfo(menuData,aniName)
    ---开始表演
    self:StartBullet()
    self:StartTimer(menuData)
end

function OverseaManageMenuSettingPutNode:StartTimer(menuData)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local baseTime = component:GetMenuBaseTime()
    local remainTime =  menuData.remainTime - os.time()
    self.RemainCount = math.ceil(remainTime/tonumber(baseTime))
    self.RemainNum.text =  self.RemainCount
    self.SellTime.text = CfUtils.GetTimeHMS(checkNumber(remainTime))
    self:RemoveTimer()
    if remainTime > 0  then
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                self.SellTime.text = CfUtils.GetTimeHMS(checkNumber(count))
                self.RemainCount = math.ceil(count/tonumber(baseTime))
                self.RemainNum.text = self.RemainCount
            else
                self.SellTime.text = CfUtils.GetTimeHMS(checkNumber(0))
                self.RemainNum.text = 0
                self.RemainCount = 0
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.Timer = nil
                --component:RefreshMenuRedPoint()
                if self.callBack then
                    self.callBack(self.index)
                end
            end
        end, remainTime + 1, false, true)
    end
end

function OverseaManageMenuSettingPutNode:RemoveTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end

---当前菜品是否和今日翻倍料理一致 一致的话就显示name1 不一致显示name2
function OverseaManageMenuSettingPutNode:IsMeetRecipes(menuData)
    local isMeet = false
    local foodData = menuData.saleRecipes
    local todayFoodData = menuData.packages

    local index = 0
    for i = 1, #foodData do
        if isTable(todayFoodData) and todayFoodData[i] and foodData[i].recipeId == todayFoodData[i].recipeId then
            index = index + 1
        end
    end
    if index == #foodData then
       isMeet = true
    end
    return isMeet
end

function OverseaManageMenuSettingPutNode:SetFoodTypeInfo(menuData,aniName)
    local foodData = menuData.saleRecipes
    local _PosAndScale = PosAndScale[#foodData]
    for i = 1, FoodTypeCount do
        if foodData and foodData[i] then
            KTool.SetActive(self.foodTypeEnv[i].BtnNode.gameObject,true)
            if aniName then
                self.foodTypeEnv[i]:PlayAniByName(aniName)
            end
            self.foodTypeEnv[i]:RefreshPutFoodTypeShow(foodData[i])
            self.foodTypeEnv[i]:RefreshPosAndScale(_PosAndScale[i])
        else
            KTool.SetActive(self.foodTypeEnv[i].BtnNode.gameObject,false)
        end
    end
end

function OverseaManageMenuSettingPutNode:StartBullet()
    self:StopBulletCo()
    self.co = cs_coroutine.start(function()
        self.isStart = true
        local osTimes = {}
        while self.isStart do
            local go = self:GetDescNodeGo()
            if isNull(go) then
                go = CS.UnityEngine.GameObject.Instantiate(self.DescNode.gameObject)
                KTool.SetParent(go,self.DescNode.transform.parent.gameObject,false)
            end
            KTool.SetActive(go,true)
            coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.85))
            table.insert(osTimes,{go = go ,time = os.time() + 1.7,isVisable = true})
            for i = #osTimes, 1, -1 do
                if os.time() >= osTimes[i].time and osTimes[i].isVisable then
                    KTool.SetActive(osTimes[i].go,false)
                    osTimes[i].isVisable = false
                    self:InsertDescNodeGo(osTimes[i].go)
                    table.remove(osTimes,i)
                end
            end
        end
    end)
end

function OverseaManageMenuSettingPutNode:GetShowStr(name)
    local str = ""
    local curGroup = MaidCoffeeMgr:GetInstance():GetMenuGroup()
    local ids = MaidCoffeeUtils.GetPutOnAniIds(curGroup)
    local isNotFind = true
    local strId
    while isNotFind do
        local randomIndex = math.random(1,table.count(ids))
        local _strId = ids[randomIndex]
        if not self.usedStrIds[name] then
            self.usedStrIds[name] = _strId
            strId = _strId
            isNotFind = false
        end
    end
    if strId then
        local vo = MaidCoffeeUtils.GetMaidCoffeeAniTxtVo(strId)
        str = vo.decr
    end

    return str
end

function OverseaManageMenuSettingPutNode:GetDescNodeGo()
    local go = nil
    if self.cacheNode[1] then
        go = self.cacheNode[1]
        local env = CfUtils.GetLuaScr(go,"Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManageSettingBulletCell")
        local str = self:GetShowStr(go.name)
        env:SetTxt(str)
        table.remove(self.cacheNode,1)
        return go
    end
end

function OverseaManageMenuSettingPutNode:InsertDescNodeGo(go)
    self.usedStrIds[go.name] = nil
    table.insert(self.cacheNode,go)
end

function OverseaManageMenuSettingPutNode:StopBulletCo()
    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
        self.usedStrIds = {}
    end
    self.cacheNode = {}
    for i = 0, self.DescNode.transform.parent.childCount - 1 do
        local go = self.DescNode.transform.parent.transform:GetChild(i)
        KTool.SetActive(go.gameObject,false)
        table.insert(self.cacheNode,go)
    end
    self.isStart = false
end

function OverseaManageMenuSettingPutNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:StopBulletCo()
    self:RemoveTimer()
    self:Delete()
end

---下架
function OverseaManageMenuSettingPutNode:OnPutOffBtnClick()
    GameUtils.SecondConfirm
    (
            localize("是否下架当前套餐？"),
            function()
                GameUtils.Request(Interfaces.MaidCoffeeMenuCancel,{ menuId = self.index },
                        function(request,response)
                            if response.errCode == 0 then
                                local data = response.data
                                local pRewards = data.rewards
                                local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                                local maidCoffeeHomeDojo = component:GetMaidCoffeeHomeDoJo()
                                self:StopBulletCo()
                                self:RemoveTimer()
                                maidCoffeeHomeDojo:CancelMenuData(self.index)
                                --component:RefreshMenuRedPoint()
                                if not isNull(pRewards) and #pRewards > 0 then
                                    GoodsUtils.DrawRewards(pRewards, true)
                                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = pRewards ,cb  = function()
                                        if self.callBack then
                                            self.callBack(self.index)
                                        end
                                    end} })
                                else
                                    if self.callBack then
                                        self.callBack(self.index)
                                    end
                                end
                            end
                        end)
            end,nil,localize("将会返还剩余未售卖的套餐总成本")
    )
end

function OverseaManageMenuSettingPutNode:OnBtnRecommendClick()
    local data = {}
    for i, v in pairs(self.menuData.saleRecipes) do
        table.insert(data,{refId = v.recipeId})
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeRecommend, parameters = {
        curIndex = self.index,curData = data
    }})
end

function OverseaManageMenuSettingPutNode:OnBtnFastSellingClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFastSellDialog, parameters = {
        curIndex = self.index, maxNum = self.RemainCount
    }})
end

return OverseaManageMenuSettingPutNode